async (page) => {
await page.goto('http://127.0.0.1:8765/agent');
const seq=[];
await page.keyboard.press('Tab');
const first=await page.evaluate(()=>{const e=document.activeElement;const r=e.getBoundingClientRect();const cs=getComputedStyle(e);return {t:e.textContent.trim(),href:e.getAttribute('href'),x:r.x,y:r.y,w:r.width,h:r.height,outline:cs.outlineStyle+' '+cs.outlineWidth,vis:cs.visibility}});
await page.keyboard.press('Enter');
const after=await page.evaluate(()=>({hash:location.hash,active:document.activeElement.id||document.activeElement.tagName,txt:document.activeElement.textContent.trim().slice(0,40),top:document.querySelector('h1').getBoundingClientRect().top}));
await page.goto('http://127.0.0.1:8765/agent');
for(let i=0;i<14;i++){await page.keyboard.press('Tab');seq.push(await page.evaluate(()=>{const e=document.activeElement;const cs=getComputedStyle(e);return (e.textContent||'').trim().slice(0,25)+'|'+cs.outlineStyle+cs.outlineWidth})) }
await page.setViewportSize({width:390,height:844});
const ov=await page.evaluate(()=>[document.documentElement.scrollWidth,innerWidth]);
await page.screenshot({path:'m.png'});
const ov2=[];
for(const u of ['/','/chaine','/outillage','/entites/ENT-A']){await page.goto('http://127.0.0.1:8765'+u);ov2.push(u+await page.evaluate(()=>document.documentElement.scrollWidth));}
await page.setViewportSize({width:1280,height:800});
return {first,after,seq,ov,ov2};
}

